package com.skripsi.chefly.data.repository

import android.content.Context
import android.util.Log
import com.skripsi.chefly.data.Recipe
import com.skripsi.chefly.data.local.AppDatabase
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.runBlocking
import kotlinx.coroutines.withContext
import java.util.concurrent.ConcurrentHashMap

/**
 * Singleton repository with pagination support.
 * Reads from Room (prepackaged DB) in background threads.
 */
object RecipeRepository {
    private var initialized = false
    private val recipeTokenMap: MutableMap<String, Set<String>> = ConcurrentHashMap()
    private var cachedAllRecipes: List<Recipe>? = null  // Cache untuk all recipes
    private val TAG = "RecipeRepository"
    private const val PAGE_SIZE = 30 // Load 30 recipes per page

    // Use the AppDatabase.getDatabase(...) helper defined in AppDatabase.kt
    private fun getDb(context: Context) = AppDatabase.getDatabase(context)
    private fun getDao(context: Context) = getDb(context).recipeDao()

    // Ensure DB instance is created. Room will copy the prepackaged DB from assets.
    fun init(context: Context) {
        if (initialized) return
        try {
            // Touch DB to trigger createFromAsset copy if needed
            runBlocking { getDao(context).getAllOnceCount() }
            Log.d(TAG, "RecipeRepository initialized successfully")
            initialized = true
        } catch (e: Exception) {
            Log.e(TAG, "Failed to initialize RecipeRepository: ${e.message}")
        }
    }

    /**
     * Get total recipe count
     */
    suspend fun getRecipeCount(context: Context): Int = withContext(Dispatchers.IO) {
        try {
            getDao(context).getAllOnceCount()
        } catch (e: Exception) {
            Log.e(TAG, "Error getting recipe count: ${e.message}")
            0
        }
    }

    /**
     * Get paginated recipes
     * @param pageNumber 0-based page number
     */
    suspend fun getRecipesPaged(context: Context, pageNumber: Int): List<Recipe> =
        withContext(Dispatchers.IO) {
        try {
            val offset = pageNumber * PAGE_SIZE
            val limit = PAGE_SIZE
            val entities = getDao(context).getRecipesPaginated(limit, offset)
            Log.d(TAG, "Loaded page $pageNumber with ${entities.size} recipes")
            entities.map { it.toRecipe() }
        } catch (e: Exception) {
            Log.e(TAG, "Error loading recipes for page $pageNumber: ${e.message}")
            emptyList()
        }
    }

    fun getAllRecipes(context: Context): List<Recipe> = runBlocking {
        val entities = getDao(context).getAllOnceList()
        entities.map { it.toRecipe() }
    }

    // Suspend version with caching for better performance
    private suspend fun getAllRecipesSuspend(context: Context): List<Recipe> = withContext(Dispatchers.IO) {
        if (cachedAllRecipes != null) {
            return@withContext cachedAllRecipes!!
        }
        try {
            val entities = getDao(context).getAllOnceList()
            val recipes = entities.map { it.toRecipe() }
            cachedAllRecipes = recipes
            recipes
        } catch (e: Exception) {
            Log.e(TAG, "Error getting all recipes: ${e.message}")
            emptyList()
        }
    }

    suspend fun getRecipeById(context: Context, id: String): Recipe? = withContext(Dispatchers.IO) {
        try {
            getDao(context).getById(id)?.toRecipe()
        } catch (e: Exception) {
            Log.e(TAG, "Error getting recipe by id: ${e.message}")
            null
        }
    }

    suspend fun searchRecipesByQuery(context: Context, query: String): List<Recipe> =
        withContext(Dispatchers.IO) {
        if (query.isBlank()) return@withContext getAllRecipesSuspend(context)
        val q = query.lowercase().trim()
        val recipes = getAllRecipesSuspend(context)
        // Switch to Default for the CPU-intensive filtering
        withContext(Dispatchers.Default) {
            recipes.filter { recipe ->
                val nameMatches = recipe.name.lowercase().contains(q)
                val tokens: Set<String> = recipe.id?.let { recipeTokenMap[it] } ?: computeTokensForRecipe(recipe)
                val tokenMatches = tokens.any { it.contains(q) }
                nameMatches || tokenMatches
            }
        }
    }

    suspend fun searchRecipesByIngredientsSusp(context: Context, detectedIngredients: List<String>): List<Recipe> =
        withContext(Dispatchers.Default) {
        if (detectedIngredients.isEmpty()) return@withContext emptyList()
        val normalizedDetected = detectedIngredients
            .flatMap { splitAndNormalizeIngredient(it) }
            .filter { it.isNotBlank() }
            .toSet()

        val recipes = getAllRecipesSuspend(context)

        val results = recipes.mapNotNull { recipe ->
            val recipeTokens = recipe.ingredientList.flatMap { splitAndNormalizeIngredient(it) }.filter { it.isNotBlank() }.toSet()
            if (recipeTokens.isEmpty()) return@mapNotNull null

            val intersectionSize = normalizedDetected.intersect(recipeTokens).size
            if (intersectionSize == 0) return@mapNotNull null

            val unionSize = normalizedDetected.union(recipeTokens).size.coerceAtLeast(1)

            val coverageScore = intersectionSize.toFloat() / recipeTokens.size
            val jaccardScore = intersectionSize.toFloat() / unionSize

            val finalScore = (coverageScore * 0.7f) + (jaccardScore * 0.3f)

            recipe to finalScore
        }
            .sortedByDescending { it.second }
            .map { it.first }

        return@withContext results
    }

    fun getMatchingIngredientsCount(context: Context, id: String, detectedIngredients: List<String>): Pair<Int, Int>? {
        val r = runBlocking { getDao(context).getById(id)?.toRecipe() } ?: return null
        if (detectedIngredients.isEmpty()) return 0 to r.ingredientList.size

        val normalizedDetected = detectedIngredients.flatMap { splitAndNormalizeIngredient(it) }.filter { it.isNotBlank() }.toSet()
        val recipeTokens = r.ingredientList.flatMap { splitAndNormalizeIngredient(it) }.filter { it.isNotBlank() }.toSet()

        val matched = normalizedDetected.intersect(recipeTokens).size
        return matched to recipeTokens.size
    }

    // Tokenization helpers (kept from original implementation)
    private fun splitAndNormalizeIngredient(text: String): List<String> {
        val cleaned = text
            .lowercase()
            .replace("(", "")
            .replace(")", "")
            .replace("[", "")
            .replace("]", "")
            .replace("\"", "")
            .replace(Regex("[^a-z0-9\\s-]"), " ")
            .replace(Regex("\\s{2,}"), " ")

        return cleaned
            .split(Regex("[,;:/\\-]|\\s+"))
            .map { it.trim() }
            .filter { it.isNotEmpty() }
    }

    private fun computeTokensForRecipe(recipe: Recipe): Set<String> {
        val nameTokens = (recipe.titleCleaned?.lowercase() ?: recipe.name.lowercase())
        val ingredientTokens = recipe.ingredientList.flatMap { splitAndNormalizeIngredient(it) }
        val combined = mutableSetOf<String>()
        combined.addAll(nameTokens.split(Regex("\\s+")))
        combined.addAll(ingredientTokens.map { it.lowercase() })
        return combined.filter { it.isNotBlank() }.toSet()
    }
}

package com.skripsi.chefly.data.repository

import android.content.Context
import android.util.Log
import com.skripsi.chefly.data.Recipe
import com.skripsi.chefly.data.local.AppDatabase
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.runBlocking
import kotlinx.coroutines.withContext
import java.util.concurrent.ConcurrentHashMap

/**
 * Singleton repository with pagination support.
 * Reads from Room (prepackaged DB) in background threads.
 */
object RecipeRepository {
    private var initialized = false
    private val recipeTokenMap: MutableMap<String, Set<String>> = ConcurrentHashMap()
    private var cachedAllRecipes: List<Recipe>? = null  // Cache untuk all recipes
    private val TAG = "RecipeRepository"
    private const val PAGE_SIZE = 30 // Load 30 recipes per page

    // Use the AppDatabase.getDatabase(...) helper defined in AppDatabase.kt
    private fun getDb(context: Context) = AppDatabase.getDatabase(context)
    private fun getDao(context: Context) = getDb(context).recipeDao()

    // Ensure DB instance is created. Room will copy the prepackaged DB from assets.
    fun init(context: Context) {
        if (initialized) return
        try {
            // Touch DB to trigger createFromAsset copy if needed
            runBlocking { getDao(context).getAllOnceCount() }
            Log.d(TAG, "RecipeRepository initialized successfully")
            initialized = true
        } catch (e: Exception) {
            Log.e(TAG, "Failed to initialize RecipeRepository: ${e.message}")
        }
    }

    /**
     * Get total recipe count
     */
    suspend fun getRecipeCount(context: Context): Int = withContext(Dispatchers.IO) {
        try {
            getDao(context).getAllOnceCount()
        } catch (e: Exception) {
            Log.e(TAG, "Error getting recipe count: ${e.message}")
            0
        }
    }

    /**
     * Get paginated recipes
     * @param pageNumber 0-based page number
     */
    suspend fun getRecipesPaged(context: Context, pageNumber: Int): List<Recipe> =
        withContext(Dispatchers.IO) {
        try {
            val offset = pageNumber * PAGE_SIZE
            val limit = PAGE_SIZE
            val entities = getDao(context).getRecipesPaginated(limit, offset)
            Log.d(TAG, "Loaded page $pageNumber with ${entities.size} recipes")
            entities.map { it.toRecipe() }
        } catch (e: Exception) {
            Log.e(TAG, "Error loading recipes for page $pageNumber: ${e.message}")
            emptyList()
        }
    }

    fun getAllRecipes(context: Context): List<Recipe> = runBlocking {
        val entities = getDao(context).getAllOnceList()
        entities.map { it.toRecipe() }
    }

    // Suspend version with caching for better performance
    private suspend fun getAllRecipesSuspend(context: Context): List<Recipe> = withContext(Dispatchers.IO) {
        if (cachedAllRecipes != null) {
            return@withContext cachedAllRecipes!!
        }
        try {
            val entities = getDao(context).getAllOnceList()
            val recipes = entities.map { it.toRecipe() }
            cachedAllRecipes = recipes
            recipes
        } catch (e: Exception) {
            Log.e(TAG, "Error getting all recipes: ${e.message}")
            emptyList()
        }
    }

    suspend fun getRecipeById(context: Context, id: String): Recipe? = withContext(Dispatchers.IO) {
        try {
            getDao(context).getById(id)?.toRecipe()
        } catch (e: Exception) {
            Log.e(TAG, "Error getting recipe by id: ${e.message}")
            null
        }
    }

    suspend fun searchRecipesByQuery(context: Context, query: String): List<Recipe> =
        withContext(Dispatchers.IO) {
        if (query.isBlank()) return@withContext getAllRecipesSuspend(context)
        val q = query.lowercase().trim()
        val recipes = getAllRecipesSuspend(context)
        // Switch to Default for the CPU-intensive filtering
        withContext(Dispatchers.Default) {
            recipes.filter { recipe ->
                val nameMatches = recipe.name.lowercase().contains(q)
                val tokens: Set<String> = recipe.id?.let { recipeTokenMap[it] } ?: computeTokensForRecipe(recipe)
                val tokenMatches = tokens.any { it.contains(q) }
                nameMatches || tokenMatches
            }
        }
    }

    suspend fun searchRecipesByIngredientsSusp(context: Context, detectedIngredients: List<String>): List<Recipe> =
        withContext(Dispatchers.IO) {
        if (detectedIngredients.isEmpty()) return@withContext emptyList()

        val recipes = getAllRecipesSuspend(context)

        // Switch to Default for the CPU-intensive scoring calculation
        withContext(Dispatchers.Default) {
            val normalizedDetected = detectedIngredients
                .flatMap { splitAndNormalizeIngredient(it) }
                .filter { it.isNotBlank() }
                .toSet()

            val results = recipes.mapNotNull { recipe ->
                val recipeTokens = recipe.ingredientList.flatMap { splitAndNormalizeIngredient(it) }.filter { it.isNotBlank() }.toSet()
                if (recipeTokens.isEmpty()) return@mapNotNull null

                val intersectionSize = normalizedDetected.intersect(recipeTokens).size
                if (intersectionSize == 0) return@mapNotNull null

                val unionSize = normalizedDetected.union(recipeTokens).size.coerceAtLeast(1)

                val coverageScore = intersectionSize.toFloat() / recipeTokens.size
                val jaccardScore = intersectionSize.toFloat() / unionSize

                val finalScore = (coverageScore * 0.7f) + (jaccardScore * 0.3f)

                recipe to finalScore
            }
                .sortedByDescending { it.second }
                .map { it.first }

            results
        }
    }

    fun getMatchingIngredientsCount(context: Context, id: String, detectedIngredients: List<String>): Pair<Int, Int>? {
        val r = runBlocking { getDao(context).getById(id)?.toRecipe() } ?: return null
        if (detectedIngredients.isEmpty()) return 0 to r.ingredientList.size

        val normalizedDetected = detectedIngredients.flatMap { splitAndNormalizeIngredient(it) }.filter { it.isNotBlank() }.toSet()
        val recipeTokens = r.ingredientList.flatMap { splitAndNormalizeIngredient(it) }.filter { it.isNotBlank() }.toSet()

        val matched = normalizedDetected.intersect(recipeTokens).size
        return matched to recipeTokens.size
    }

    // Tokenization helpers (kept from original implementation)
    private fun splitAndNormalizeIngredient(text: String): List<String> {
        val cleaned = text
            .lowercase()
            .replace("(", "")
            .replace(")", "")
            .replace("[", "")
            .replace("]", "")
            .replace("\"", "")
            .replace(Regex("[^a-z0-9\\s-]"), " ")
            .replace(Regex("\\s{2,}"), " ")

        return cleaned
            .split(Regex("[,;:/\\-]|\\s+"))
            .map { it.trim() }
            .filter { it.isNotEmpty() }
    }

    private fun computeTokensForRecipe(recipe: Recipe): Set<String> {
        val nameTokens = (recipe.titleCleaned?.lowercase() ?: recipe.name.lowercase())
        val ingredientTokens = recipe.ingredientList.flatMap { splitAndNormalizeIngredient(it) }
        val combined = mutableSetOf<String>()
        combined.addAll(nameTokens.split(Regex("\\s+")))
        combined.addAll(ingredientTokens.map { it.lowercase() })
        return combined.filter { it.isNotBlank() }.toSet()
    }
}

package com.skripsi.chefly.data
import androidx.room.Entity import androidx.room.PrimaryKey
/** * Shopping List entity untuk menyimpan shopping list history */ @Entity(tableName = "shopping_lists") data class ShoppingListEntity( @PrimaryKey val id: String, val name: String, val createdAt: Long, val updatedAt: Long, val recipeIds: String, // JSON array of recipe IDs val itemsJson: String // JSON serialized list )
/** * Shopping List data model */ data class ShoppingList( val id: String, val name: String, val items: List<ShoppingItem>, val createdAt: Long, val updatedAt: Long, val recipeIds: List<String> )
/** * Individual shopping item */ data class ShoppingItem( val id: String, val ingredient: String, val quantity: String, val unit: String, // "pcs", "kg", "gram", "tbsp", "cup" val category: String, // "Sayuran", "Daging", "Bumbu", etc val estimatedPrice: Double, val notes: String, val isChecked: Boolean )
/** * Request model untuk generate shopping list */ data class GenerateShoppingListRequest( val recipeIds: List<String>, val name: String = "Shopping List", val excludeFridgeItems: Boolean = true, // Exclude items already in fridge val fridgeItems: List<String> = emptyList() )
/** * Response model untuk shopping list generation */ data class GenerateShoppingListResponse( val shoppingList: ShoppingList, val totalEstimatedCost: Double, val itemCount: Int, val message: String )

package com.skripsi.chefly.data.repository

import android.content.Context
import android.util.Log
import com.skripsi.chefly.data.ShoppingItem
import com.skripsi.chefly.data.ShoppingList
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import kotlin.random.Random

/**
 * Shopping List Repository
 * Handles all shopping list operations
 */
object ShoppingListRepository {
    private val TAG = "ShoppingListRepository"

    // Ingredient pricing database (sesuaikan dengan market real)
    private val ingredientPrices = mapOf(
        // Sayuran
        "bayam" to Pair("Sayuran", 5000.0),
        "kangkung" to Pair("Sayuran", 4000.0),
        "selada" to Pair("Sayuran", 6000.0),
        "tomat" to Pair("Sayuran", 8000.0),
        "terong" to Pair("Sayuran", 5000.0),
        "wortel" to Pair("Sayuran", 6000.0),
        "kentang" to Pair("Sayuran", 4000.0),
        "jagung" to Pair("Sayuran", 3000.0),
        "brokoli" to Pair("Sayuran", 12000.0),

        // Daging
        "daging sapi" to Pair("Daging & Protein", 85000.0),
        "daging ayam" to Pair("Daging & Protein", 35000.0),
        "daging kambing" to Pair("Daging & Protein", 90000.0),
        "telur ayam" to Pair("Daging & Protein", 2000.0),
        "tahu" to Pair("Daging & Protein", 8000.0),
        "tempe" to Pair("Daging & Protein", 6000.0),
        "ikan lele" to Pair("Daging & Protein", 25000.0),

        // Bumbu
        "bawang merah" to Pair("Bumbu & Saus", 12000.0),
        "bawang putih" to Pair("Bumbu & Saus", 18000.0),
        "cabe merah" to Pair("Bumbu & Saus", 15000.0),
        "cabe rawit" to Pair("Bumbu & Saus", 20000.0),
        "jahe" to Pair("Bumbu & Saus", 8000.0),
        "kunyit" to Pair("Bumbu & Saus", 5000.0),
        "kecap manis" to Pair("Bumbu & Saus", 10000.0),
        "garam" to Pair("Bumbu & Saus", 3000.0),

        // Tepung & Karbo
        "tepung terigu" to Pair("Tepung & Karbo", 8000.0),
        "beras" to Pair("Tepung & Karbo", 10000.0),
        "nasi" to Pair("Tepung & Karbo", 15000.0),
    )

    /**
     * Generate shopping list dari selected recipes
     */
    suspend fun generateShoppingList(
        context: Context,
        recipeIds: List<String>,
        excludeFridgeItems: List<String> = emptyList(),
        listName: String = "Shopping List"
    ): ShoppingList = withContext(Dispatchers.Default) {
        try {
            val shoppingItems = mutableListOf<ShoppingItem>()
            val ingredientMap = mutableMapOf<String, ShoppingItem>() // For merging duplicates

            // Get recipes dari database
            for (recipeId in recipeIds) {
                try {
                    val recipe = RecipeRepository.getRecipeById(context, recipeId) ?: continue

                    // Parse ingredients dari recipe
                    val ingredients = parseIngredients(recipe.rawIngredients)

                    // Process each ingredient
                    for ((name, quantity, unit) in ingredients) {
                        val normalized = name.lowercase().trim()

                        // Skip jika sudah ada di fridge
                        if (excludeFridgeItems.any { it.lowercase().contains(normalized) || normalized.contains(it.lowercase()) }) {
                            continue
                        }

                        // Find price dari database
                        val (category, price) = ingredientPrices[normalized] ?: findClosestPrice(normalized)

                        val item = ShoppingItem(
                            id = "${normalized}_${Random.nextInt()}",
                            ingredient = name,
                            quantity = quantity,
                            unit = unit,
                            category = category,
                            estimatedPrice = price,
                            notes = "Dari resep: ${recipe.name}",
                            isChecked = false
                        )

                        // Merge jika ingredient sudah ada
                        ingredientMap[normalized]?.let {
                            val merged = ShoppingItem(
                                id = it.id,
                                ingredient = it.ingredient,
                                quantity = "${it.quantity} + ${quantity}",
                                unit = unit,
                                category = category,
                                estimatedPrice = price,
                                notes = "${it.notes}, Dari resep: ${recipe.name}",
                                isChecked = false
                            )
                            ingredientMap[normalized] = merged
                        } ?: run {
                            ingredientMap[normalized] = item
                        }
                    }
                } catch (e: Exception) {
                    Log.e(TAG, "Error processing recipe $recipeId: ${e.message}")
                }
            }

            shoppingItems.addAll(ingredientMap.values)

            // Sort by category
            shoppingItems.sortBy { it.category }

            ShoppingList(
                id = "SL_${System.currentTimeMillis()}",
                name = listName,
                items = shoppingItems,
                createdAt = System.currentTimeMillis(),
                updatedAt = System.currentTimeMillis(),
                recipeIds = recipeIds
            )
        } catch (e: Exception) {
            Log.e(TAG, "Error generating shopping list: ${e.message}")
            ShoppingList(
                id = "SL_${System.currentTimeMillis()}",
                name = listName,
                items = emptyList(),
                createdAt = System.currentTimeMillis(),
                updatedAt = System.currentTimeMillis(),
                recipeIds = recipeIds
            )
        }
    }

    /**
     * Parse ingredients dari raw string
     * Format: "1 buah tomat", "2 sdm minyak", etc
     */
    private fun parseIngredients(rawIngredients: String): List<Triple<String, String, String>> {
        val result = mutableListOf<Triple<String, String, String>>()

        try {
            // Split by comma atau newline
            val parts = rawIngredients.split(",", "\n", "--").map { it.trim() }

            for (part in parts) {
                if (part.isBlank()) continue

                // Try to extract: quantity + unit + ingredient
                val regex = """^(\d+(?:\.\d+)?|\d+\s*-\s*\d+)?\s*([a-zA-Z]+|[\u0000-\u007F]*)?\s*(.+)$""".toRegex()
                val match = regex.find(part)

                if (match != null) {
                    val quantity = match.groupValues[1].ifEmpty { "1" }.trim()
                    val unit = match.groupValues[2].ifEmpty { "pcs" }.trim()
                    val ingredient = match.groupValues[3].trim()

                    if (ingredient.isNotEmpty()) {
                        result.add(Triple(ingredient, quantity, unit))
                    }
                } else {
                    // Fallback: treat entire string as ingredient
                    result.add(Triple(part, "1", "pcs"))
                }
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error parsing ingredients: ${e.message}")
        }

        return result
    }

    /**
     * Find closest price match using fuzzy matching
     */
    private fun findClosestPrice(ingredientName: String): Pair<String, Double> {
        val name = ingredientName.lowercase()

        // Simple fuzzy matching
        for ((key, value) in ingredientPrices) {
            if (name.contains(key) || key.contains(name)) {
                return value
            }
        }

        // Default price jika tidak ketemu
        return Pair("Lainnya", 10000.0)
    }

    /**
     * Calculate total price
     */
    fun calculateTotalPrice(items: List<ShoppingItem>): Double {
        return items.sumOf { it.estimatedPrice }
    }

    /**
     * Update item checked status
     */
    fun updateItemChecked(items: List<ShoppingItem>, itemId: String, isChecked: Boolean): List<ShoppingItem> {
        return items.map {
            if (it.id == itemId) it.copy(isChecked = isChecked) else it
        }
    }

    /**
     * Export shopping list ke text format
     */
    fun exportAsText(shoppingList: ShoppingList): String {
        val sb = StringBuilder()
        sb.append("${shoppingList.name}\n")
        sb.append("Created: ${java.text.SimpleDateFormat("dd/MM/yyyy HH:mm").format(shoppingList.createdAt)}\n")
        sb.append("Total: ${String.format("Rp %,d", calculateTotalPrice(shoppingList.items).toInt())}\n")
        sb.append("\n")

        // Group by category
        val grouped = shoppingList.items.groupBy { it.category }
        for ((category, items) in grouped) {
            sb.append("$category:\n")
            for (item in items) {
                val checked = if (item.isChecked) "✓" else "☐"
                sb.append("  $checked ${item.ingredient} (${item.quantity} ${item.unit}) - Rp ${item.estimatedPrice.toInt()}\n")
            }
            sb.append("\n")
        }

        return sb.toString()
    }
}

package com.skripsi.chefly.ui.screens

import androidx.compose.foundation.background
import androidx.compose.foundation.clickable
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.filled.ArrowBack
import androidx.compose.material.icons.filled.Check
import androidx.compose.material.icons.filled.Close
import androidx.compose.material.icons.filled.Delete
import androidx.compose.material.icons.filled.MoreVert
import androidx.compose.material.icons.filled.Share
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.style.TextDecoration
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import com.skripsi.chefly.data.ShoppingList
import com.skripsi.chefly.data.ShoppingItem
import com.skripsi.chefly.data.repository.ShoppingListRepository
import kotlinx.coroutines.launch

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun ShoppingListScreen(
    shoppingList: ShoppingList?,
    onBackClick: () -> Unit,
    onGenerateNewList: () -> Unit
) {
    val context = LocalContext.current
    val scope = rememberCoroutineScope()
    var currentList by remember { mutableStateOf(shoppingList) }
    var showDeleteDialog by remember { mutableStateOf(false) }
    var selectedItemToDelete by remember { mutableStateOf<String?>(null) }

    if (currentList == null) {
        Scaffold(
            topBar = {
                TopAppBar(
                    title = { Text("Shopping List") },
                    navigationIcon = {
                        IconButton(onClick = onBackClick) {
                            Icon(Icons.Default.ArrowBack, contentDescription = "Back")
                        }
                    }
                )
            }
        ) { padding ->
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(padding),
                contentAlignment = Alignment.Center
            ) {
                Column(
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    Text("No shopping list yet", style = MaterialTheme.typography.headlineSmall)
                    Button(onClick = onGenerateNewList) {
                        Text("Generate Shopping List")
                    }
                }
            }
        }
        return
    }

    val totalPrice = ShoppingListRepository.calculateTotalPrice(currentList.items)
    val checkedCount = currentList.items.count { it.isChecked }
    val groupedByCategory = currentList.items.groupBy { it.category }

    if (showDeleteDialog && selectedItemToDelete != null) {
        AlertDialog(
            onDismissRequest = { showDeleteDialog = false },
            title = { Text("Delete Item?") },
            text = { Text("Are you sure you want to delete this item?") },
            confirmButton = {
                Button(
                    onClick = {
                        currentList = currentList.copy(
                            items = currentList.items.filterNot { it.id == selectedItemToDelete }
                        )
                        showDeleteDialog = false
                        selectedItemToDelete = null
                    }
                ) {
                    Text("Delete")
                }
            },
            dismissButton = {
                TextButton(onClick = { showDeleteDialog = false }) {
                    Text("Cancel")
                }
            }
        )
    }

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text(currentList.name) },
                navigationIcon = {
                    IconButton(onClick = onBackClick) {
                        Icon(Icons.Default.ArrowBack, contentDescription = "Back")
                    }
                },
                actions = {
                    IconButton(onClick = {
                        // Share functionality
                        val text = ShoppingListRepository.exportAsText(currentList)
                        // TODO: Implement share
                    }) {
                        Icon(Icons.Default.Share, contentDescription = "Share")
                    }
                }
            )
        }
    ) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
        ) {
            // Header dengan stats
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(12.dp),
                colors = CardDefaults.cardColors(
                    containerColor = MaterialTheme.colorScheme.primaryContainer
                )
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(16.dp),
                    verticalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Column {
                            Text(
                                "Total Items",
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.onPrimaryContainer
                            )
                            Text(
                                "${currentList.items.size} items",
                                style = MaterialTheme.typography.headlineSmall,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.onPrimaryContainer
                            )
                        }

                        Column(
                            horizontalAlignment = Alignment.End
                        ) {
                            Text(
                                "Progress",
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.onPrimaryContainer
                            )
                            Text(
                                "$checkedCount/${currentList.items.size}",
                                style = MaterialTheme.typography.headlineSmall,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.onPrimaryContainer
                            )
                        }

                        Column(
                            horizontalAlignment = Alignment.End
                        ) {
                            Text(
                                "Est. Cost",
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.onPrimaryContainer
                            )
                            Text(
                                "Rp ${String.format("%,d", totalPrice.toInt())}",
                                style = MaterialTheme.typography.headlineSmall,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.onPrimaryContainer
                            )
                        }
                    }

                    // Progress bar
                    LinearProgressIndicator(
                        progress = { if (currentList.items.isEmpty()) 0f else checkedCount.toFloat() / currentList.items.size },
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(4.dp)
                    )
                }
            }

            // Shopping items grouped by category
            LazyColumn(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(horizontal = 12.dp),
                verticalArrangement = Arrangement.spacedBy(8.dp),
                contentPadding = PaddingValues(bottom = 16.dp)
            ) {
                groupedByCategory.forEach { (category, items) ->
                    item {
                        Text(
                            category,
                            style = MaterialTheme.typography.labelLarge,
                            fontWeight = FontWeight.SemiBold,
                            modifier = Modifier.padding(top = 8.dp, bottom = 4.dp)
                        )
                    }

                    items(items) { item ->
                        ShoppingItemCard(
                            item = item,
                            onCheckedChange = { isChecked ->
                                currentList = currentList.copy(
                                    items = currentList.items.map {
                                        if (it.id == item.id) it.copy(isChecked = isChecked) else it
                                    }
                                )
                            },
                            onDelete = {
                                selectedItemToDelete = item.id
                                showDeleteDialog = true
                            }
                        )
                    }
                }
            }
        }
    }
}

@Composable
private fun ShoppingItemCard(
    item: ShoppingItem,
    onCheckedChange: (Boolean) -> Unit,
    onDelete: () -> Unit
) {
    Card(
        modifier = Modifier
            .fillMaxWidth()
            .clickable { onCheckedChange(!item.isChecked) },
        colors = CardDefaults.cardColors(
            containerColor = if (item.isChecked)
                MaterialTheme.colorScheme.surfaceVariant
            else
                MaterialTheme.colorScheme.surface
        ),
        elevation = CardDefaults.cardElevation(defaultElevation = 1.dp)
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(12.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            // Checkbox
            Checkbox(
                checked = item.isChecked,
                onCheckedChange = onCheckedChange,
                modifier = Modifier.size(24.dp)
            )

            // Ingredient info
            Column(
                modifier = Modifier.weight(1f),
                verticalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                Text(
                    text = item.ingredient,
                    style = MaterialTheme.typography.bodyMedium,
                    fontWeight = FontWeight.SemiBold,
                    textDecoration = if (item.isChecked) TextDecoration.LineThrough else TextDecoration.None
                )
                Text(
                    text = "${item.quantity} ${item.unit}",
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.outline
                )
                if (item.notes.isNotEmpty()) {
                    Text(
                        text = item.notes,
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.outline,
                        fontSize = 10.sp
                    )
                }
            }

            // Price
            Column(
                horizontalAlignment = Alignment.End,
                verticalArrangement = Arrangement.spacedBy(4.dp)
            ) {
                Text(
                    text = "Rp ${String.format("%,d", item.estimatedPrice.toInt())}",
                    style = MaterialTheme.typography.bodySmall,
                    fontWeight = FontWeight.Bold
                )

                // Delete button
                IconButton(
                    onClick = onDelete,
                    modifier = Modifier.size(24.dp)
                ) {
                    Icon(
                        Icons.Default.Close,
                        contentDescription = "Delete",
                        modifier = Modifier.size(16.dp),
                        tint = MaterialTheme.colorScheme.error
                    )
                }
            }
        }
    }
}
